 (() => {   "use strict";    const BACKEND_BASE_URL = "https://api.lypo.org";   const CACHE_KEY_PREFIX = "lypo_post_cache_v2_";   const CACHE_DURATION = 10 * 60 * 1000;        const titleEl = document.getElementById("postTitle");   const metaEl = document.getElementById("postMeta");   const bodyEl = document.getElementById("postBody");   const mediaEl = document.getElementById("postMedia");    if (!titleEl || !bodyEl) return;        const escapeMap = {     "&": "&amp;",     "<": "&lt;",     ">": "&gt;",     '"': "&quot;",     "'": "&#x27;",     "/": "&#x2F;"   };   const esc = (s) => String(s || "").replace(/[&<>"'\/]/g, c => escapeMap[c]);       const sanitizeUrl = (url) => {     if (!url) return "";     const urlStr = String(url).trim().toLowerCase();     if (urlStr.startsWith("javascript:") ||       urlStr.startsWith("data:") ||       urlStr.startsWith("vbscript:") ||       urlStr.startsWith("file:")) {       return "";     }     return String(url).trim();   };       const fmtDate = (iso) => {     if (!iso) return "";     try {       const date = new Date(iso);       if (isNaN(date.getTime())) return "";       return date.toLocaleDateString(undefined, {         year: 'numeric',         month: 'long',         day: 'numeric'       });     } catch {       return "";     }   };       function processContent(html) {     if (!html || typeof html !== 'string') return "";                 let processed = html;           processed = processed.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');           processed = processed.replace(/\s*on\w+\s*=\s*["'][^"']*["']/gi, '');     processed = processed.replace(/\s*on\w+\s*=\s*[^\s>]*/gi, '');           processed = processed.replace(/href\s*=\s*["']javascript:[^"']*["']/gi, 'href="#"');           return processed;   }       function getCached(slug) {     if (!slug) return null;      try {       const cached = localStorage.getItem(CACHE_KEY_PREFIX + slug);       if (!cached) return null;        const parsed = JSON.parse(cached);       if (!parsed || !parsed.data || typeof parsed.data !== 'object') {         localStorage.removeItem(CACHE_KEY_PREFIX + slug);         return null;       }        const age = Date.now() - (parsed.timestamp || 0);        if (age < CACHE_DURATION) {         return parsed.data;       }        localStorage.removeItem(CACHE_KEY_PREFIX + slug);       return null;     } catch {       return null;     }   }    function setCache(slug, data) {     if (!slug || !data || typeof data !== 'object') return;      try {       localStorage.setItem(CACHE_KEY_PREFIX + slug, JSON.stringify({         data,         timestamp: Date.now(),         version: 2       }));     } catch (e) {       console.warn("Cache write failed:", e);     }   }       function renderPost(p) {     if (!p || typeof p !== 'object') {       titleEl.textContent = "Post not found";       if (metaEl) metaEl.textContent = "";       if (mediaEl) mediaEl.innerHTML = "";       bodyEl.innerHTML = '<p class="mutedCell" role="alert">This post could not be found.</p>';       return;     }           const safeTitle = String(p.title || 'Post').trim();     document.title = `${safeTitle} • LYPO Blog`;           const safeSlug = p.slug || new URLSearchParams(window.location.search).get('slug');     if (safeSlug) {       const canonicalUrl = `https://lypo.org/post.html?slug=${safeSlug}`;               const canonicalEl = document.getElementById('dynamic-canonical') || document.querySelector('link[rel="canonical"]');       if (canonicalEl) canonicalEl.setAttribute('href', canonicalUrl);               const safeDesc = esc(p.excerpt || p.title || "Read our latest blog post").substring(0, 160);       const descEl = document.querySelector('meta[name="description"]');       if (descEl) descEl.setAttribute('content', safeDesc);        const ogUrlEl = document.querySelector('meta[property="og:url"]');       if (ogUrlEl) ogUrlEl.setAttribute('content', canonicalUrl);        const ogTitleEl = document.querySelector('meta[property="og:title"]');       if (ogTitleEl) ogTitleEl.setAttribute('content', safeTitle);        const ogDescEl = document.querySelector('meta[property="og:description"]');       if (ogDescEl) ogDescEl.setAttribute('content', safeDesc);     }           titleEl.textContent = safeTitle;     if (metaEl) metaEl.textContent = p.published_at ? fmtDate(p.published_at) : "";           const mediaParts = [];     if (p.cover_url) {       const safeCoverUrl = sanitizeUrl(p.cover_url);       if (safeCoverUrl && safeCoverUrl.startsWith('https://')) {         mediaParts.push(`<div class="postCover"><img src="${esc(safeCoverUrl)}" alt="${esc(safeTitle)}" loading="lazy" decoding="async" crossorigin="anonymous" /></div>`);       }     }     if (p.video_url) {       const safeVideoUrl = sanitizeUrl(p.video_url);       if (safeVideoUrl && (safeVideoUrl.startsWith('https://') || safeVideoUrl.startsWith('http://'))) {         mediaParts.push(`<div class="postVideo"><video controls preload="metadata" src="${esc(safeVideoUrl)}" crossorigin="anonymous"></video></div>`);       }     }     if (mediaEl) mediaEl.innerHTML = mediaParts.join("");           const content = processContent(p.content_html) || (p.excerpt ? `<p>${esc(p.excerpt)}</p>` : "");     bodyEl.innerHTML = content;   }       async function load() {          const qs = new URLSearchParams(location.search || "");     const slug = qs.get("slug") || "";      if (!slug) {       titleEl.textContent = "No post specified";       bodyEl.innerHTML = '<p class="mutedCell" role="alert">Please select a post to view.</p>';       return;     }           const safeSlug = String(slug).trim();     if (!safeSlug || safeSlug.includes('..') || safeSlug.includes('/') || safeSlug.includes('\\')) {       titleEl.textContent = "Invalid post";       bodyEl.innerHTML = '<p class="mutedCell" role="alert">Invalid post identifier.</p>';       return;     }           titleEl.textContent = "Loading...";     bodyEl.innerHTML = '<p class="mutedCell" role="status">Loading post...</p>';           const cached = getCached(safeSlug);     if (cached) {       renderPost(cached);              fetchAndCache(safeSlug, true);       return;     }           await fetchAndCache(safeSlug, false);   }       async function fetchAndCache(slug, silent = false) {     try {       const controller = new AbortController();       const timeoutId = setTimeout(() => controller.abort(), 8000);         const res = await fetch(`${BACKEND_BASE_URL}/api/blog/posts/${encodeURIComponent(slug)}`, {         signal: controller.signal,         method: 'GET',         headers: {           'Accept': 'application/json'                    },         credentials: 'omit',         mode: 'cors',         cache: 'no-cache'       });        clearTimeout(timeoutId);        if (!res.ok) {         if (res.status === 404) {           throw new Error('Post not found');         }         throw new Error(`HTTP ${res.status}`);       }               const contentType = res.headers.get('content-type');       if (!contentType || !contentType.includes('application/json')) {         throw new Error('Invalid response type');       }        const data = await res.json();        if (!data || typeof data !== 'object') {         throw new Error('Invalid response format');       }        const post = data.post;        if (!post || typeof post !== 'object') {         if (!silent) renderPost(null);         return;       }               setCache(slug, post);               if (!silent) {         renderPost(post);       }      } catch (e) {       console.error("Post load error:", e);        if (silent) return;        titleEl.textContent = "Error loading post";        const errorMsg = e.message === 'Post not found'         ? 'This post could not be found.'         : e.name === 'AbortError'           ? 'Request timed out.'           : 'Could not load post.';        bodyEl.innerHTML = `         <p class="mutedCell" role="alert">           ⚠️ ${esc(errorMsg)}            <button onclick="location.reload()" style="margin-left:8px; padding:4px 12px; background:rgba(255,255,255,.1); border:1px solid rgba(255,255,255,.2); border-radius:6px; color:inherit; cursor:pointer; font:inherit;">             Retry           </button>         </p>       `;     }   }       if (document.readyState === 'loading') {     document.addEventListener("DOMContentLoaded", load, { once: true, passive: true });   } else {     load();   } })(); 